WITH enriched AS (SELECT *, DENSE_RANK() OVER w_ordered AS quantity_dense_rank, SUM(unit_price) OVER (PARTITION BY product_id) AS product_id_sum_unit_price, RANK() OVER w_grp AS quantity_rank, AVG(unit_price) OVER (ORDER BY quantity, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS unit_price_avg_3_prior, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY product_id, order_id), 4) AS unit_price_share FROM order_items WINDOW w_ordered AS (PARTITION BY order_id, product_id ORDER BY quantity DESC NULLS LAST), w_grp AS (PARTITION BY product_id, order_id ORDER BY quantity NULLS FIRST)) SELECT id, order_id, product_id, quantity, unit_price, quantity_dense_rank, quantity_rank, unit_price_avg_3_prior, unit_price_share FROM enriched ORDER BY unit_price_share DESC, product_id;
